export interface IAccount {
  name: string;
  userId: TUserId;
  accountNumber: TBankAccountNumber;
  balance: number;
  createdAt: Date;
  updatedAt: Date | null;
}

export interface IAccountService {
  create(account: Omit<IAccount, | "createdAt" | "updatedAt">): Promise<IAccount>;
