      const data = await raw.json() as WaveResponse<IWalletTransaction[]>;

      if (!data.ok) {
        throw new Error(data.message);
      }

      return data;
    } catch (error) {
      console.error("Error fetching account transactions:", error);
      throw error;
    }
  }

