import { z } from "zod";
import { successResponseSchema, errorResponseSchema } from "@/lib/response";

export const walletAccountDTO = z.object({
  name: z.string(),
  userId: z.string(),
  accountNumber: z.string(),
  balance: z.number(),
  createdAt: z.string(),
  updatedAt: z.string().nullable(),
});

export const walletTransactionDTO = z.object({
  id: z.string(),
  userId: z.string(),
  senderAccountId: z.string(),
  senderName: z.string(),
  receiverAccountId: z.string(),
  receiverName: z.string(),
  amount: z.string(),
  status: z.enum(["pending", "success", "failed"]),
  createdAt: z.string(),
  updatedAt: z.string().nullable().optional(),
});

export const walletLedgerDTO = z.object({
  id: z.string(),
  transactionId: z.string(),
  amount: z.string(),
  entryType: z.enum(["debit", "credit"]),
  createdAt: z.string(),
  updatedAt: z.string().nullable(),
});

export const createAccountBodySchema = z.object({
  name: z.string(),
  userId: z.string(),
  accountNumber: z.union([z.string(), z.number()]).transform(String),
  balance: z.number(),
});

export const depositBodySchema = z.object({
  userId: z.string(),
  accountId: z.string(),
  amount: z.number().positive(),
});

export const depositResponseSchema = {
  body: depositBodySchema,
  response: {
    200: successResponseSchema(walletAccountDTO),
    400: errorResponseSchema,
  },
};

export const transferBodySchema = z.object({
  userId: z.string(),
  senderAccountId: z.string(),
  senderName: z.string(),
  receiverAccountId: z.string(),
  receiverName: z.string(),
  amount: z.number(),
});

export const accountNumberParamsSchema = z.object({
  accountNumber: z.string(),
});

export const accountIdParamsSchema = z.object({
  accountId: z.string(),
});

export const userIdParamsSchema = z.object({
  userId: z.string(),
});

export const transactionIdParamsSchema = z.object({
  transactionId: z.string(),
});

